{
  "modelPrompt": {
    "subject_definitions": "<Subject 1>: replacement object with appearance from <Picture 1> and motion from <Video 1>",
    "summary": "[video editing + reference generation] The target video is an edited version of <Video 1>. The original gold coins are replaced throughout by <Subject 1> while retaining all original motion, timing, camera and setting.",
    "retention_analysis": "<Subject 1>: attribute_transfer - appearance from <Picture 1> applied to coin motion\n<Video 1>: partially_preserved - motion, camera, timing and framing retained; gold coin appearance replaced",
    "detailed_description": "Retain reference appearance. [Shot 1] The <Subject 1> objects follow the exact trajectories and movements of the original gold coins in <Video 1> for the full 3 seconds, with the camera and framing preserved from the source video.",
    "overall_soundscape": "No diegetic sounds specified.",
    "non_diegetic_music": "No non-diegetic music specified."
  },
  "displayPrompt": {
    "subject_definitions": "<Subject 1>: 替换物体，外观来自 <Picture 1>，动作来自 <Video 1>",
    "summary": "[video editing + reference generation] 目标视频是 <Video 1> 的编辑版本。原金币在整个片段中被 <Subject 1> 替换，同时保留所有原始动作、时序、机位和场景。",
    "retention_analysis": "<Subject 1>: attribute_transfer - 将 <Picture 1> 的外观应用于金币动作\n<Video 1>: partially_preserved - 保留动作、机位、时序和构图；替换金币外观",
    "detailed_description": "保留参考外观。[Shot 1] <Subject 1> 物体在完整3秒内跟随 <Video 1> 中原金币的精确轨迹和运动，机位与构图完全保留源视频。",
    "overall_soundscape": "未指定任何环境音效。",
    "non_diegetic_music": "未指定任何非故事性音乐。"
  }
}
